<?php
declare(strict_types=1);
$file = __DIR__ . '/data/security_weekly.json';
$payload = is_file($file) ? json_decode((string)file_get_contents($file), true) : null;
function security_h(string $s): string { return htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$articles = is_array($payload) ? (array)($payload['articles'] ?? []) : [];
?>
<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>网络安全每周 Top 10</title><style>
*{box-sizing:border-box}body{margin:0;padding:18px;background:#f6f8fa;color:#1f2328;font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1000px;margin:auto}.head{display:flex;justify-content:space-between;align-items:end;gap:12px}.head h1{font-size:23px;margin:0}.muted{color:#656d76;font-size:13px}.sources{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.sources a{background:#eaeef2;border-radius:999px;padding:6px 10px;color:#0969da;text-decoration:none;font-size:13px}.list{display:grid;gap:10px}.item{background:#fff;border:1px solid #d1d9e0;border-radius:12px;padding:13px 15px}.meta{display:flex;gap:8px;align-items:center;color:#656d76;font-size:12px}.tag{background:#ddf4ff;color:#0550ae;border-radius:999px;padding:2px 8px}.item h2{font-size:16px;margin:6px 0}.item h2 a{color:#0969da;text-decoration:none}.summary{color:#424a53;font-size:13px;margin:5px 0}.notice{padding:16px;background:white;border:1px solid #d1d9e0;border-radius:12px}.fine{font-size:12px;color:#656d76;margin-top:10px}
</style></head><body><main class="wrap"><header class="head"><div><h1>网络安全与大模型红队 Top 10</h1><div class="muted">过去 7 天 · 漏洞/补丁、逆向分析、LLM red teaming 与 abliteration</div></div><div class="muted">更新：<?= security_h((string)($payload['updated_at'] ?? '等待首次运行')) ?></div></header><nav class="sources"><a href="https://news.ycombinator.com/" target="_blank" rel="noopener">Hacker News</a><a href="https://www.bleepingcomputer.com/" target="_blank" rel="noopener">BleepingComputer</a><a href="https://feeds.feedburner.com/TheHackersNews" target="_blank" rel="noopener">The Hacker News</a><a href="https://googleprojectzero.blogspot.com/" target="_blank" rel="noopener">Project Zero</a><a href="https://www.cisa.gov/known-exploited-vulnerabilities-catalog" target="_blank" rel="noopener">CISA KEV</a></nav>
<?php if ($articles): ?><section class="list"><?php foreach ($articles as $i => $article): ?><article class="item"><div class="meta"><span>#<?= $i+1 ?></span><span class="tag"><?= security_h((string)$article['category']) ?></span><span><?= security_h((string)$article['source']) ?></span><span><?= security_h(substr((string)$article['date'],0,10)) ?></span><?php if (isset($article['points'])): ?><span>HN ▲ <?= (int)$article['points'] ?></span><?php endif; ?></div><h2><a href="<?= security_h((string)$article['url']) ?>" target="_blank" rel="noopener"><?= security_h((string)$article['title']) ?></a></h2><?php if (!empty($article['description'])): ?><div class="summary"><?= security_h((string)$article['description']) ?></div><?php endif; ?></article><?php endforeach; ?></section><?php else: ?><div class="notice">安全新闻榜尚无缓存。首次运行后将列出公开 RSS 与 Hacker News 中过去一周的相关条目。</div><?php endif; ?>
